async function handlePartnerApiKeyRevealApi(request, response, partnerId, partnerType) {
  const config = getPartnerResourceConfig(partnerType);
  const requestUrl = new URL(request.url, `http://127.0.0.1:${PORT}`);
  const requestAdminId = getRequestAdminId(request, requestUrl);
  const requestIsSuperAdmin = isSuperAdminAuthorized(request);

  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    if (!(await requirePartnerResourcePermission({
      request,
      response,
      requestUrl,
      config,
      requestAdminId,
      requestIsSuperAdmin,
    }))) return;

    const partners = await config.read();
    const partner = findPartnerForRequest(
      partners,
      partnerId,
      requestIsSuperAdmin,
      requestAdminId,
    );
    if (!partner) {
      throw createPartnerApiError(404, `${config.label} not found.`, "PARTNER_NOT_FOUND");
    }

    const apiKey = String(partner?.apiKey ?? "").trim();
    if (!apiKey) {
      sendJson(response, 404, { message: "No API key is configured." });
      return;
    }

    sendJson(response, 200, { apiKey });
  } catch (error) {
    sendPartnerApiError(response, error, "Unable to reveal the API key.");
  }
}

async function handleAiIntegrationApiKeyRevealApi(request, response, integrationId) {
  response.setHeader("Cache-Control", "no-store, max-age=0");
  if (!requireSuperAdmin(request, response)) {
    return;
  }

  if (request.method !== "GET") {
    sendJson(response, 405, { message: "Method not allowed." });
    return;
  }

  try {
    const settings = await readWorkspaceSettings();
    const integrations = Array.isArray(settings.aiIntegrations) ? settings.aiIntegrations : [];
    const integration = findAiIntegrationById(integrations, integrationId);
    if (!integration) {
      sendJson(response, 404, { message: "AI integration not found." });
      return;
    }

    const apiKey = String(integration?.apiKey ?? "").trim();
    if (!apiKey) {
      sendJson(response, 404, { message: "No API key is configured." });
      return;
    }

    sendJson(response, 200, { apiKey });
  } catch (error) {
    sendJson(response, 500, { message: "Unable to reveal the API key." });
  }
}
